interface calc
{
    void cal(int i);
}
class displayA :calc
{
    public int x;
    public void cal(int i)
    {
        x = i * i;
    }
}
class displayB :calc
{
    public int x;
    public void cal(int i)
    {
        x = i / i;
    }
}
class Program
{
    public static void Main(string[] args)
    {
        displayA arr1 = new displayA();
        displayB arr2 = new displayB();
        arr1.x = 0;
        arr2.x = 0;
        arr1.cal(2);
        arr2.cal(2);
        Console.WriteLine(arr1.x + " " + arr2.x);
        Console.ReadLine();
    }
}

